import{c as a,Q as s,j as e,m as _}from"./chunks/framework.DOi4mjdC.js";const l="/assets/%E5%87%BD%E6%95%B0%E8%B0%83%E7%94%A8%E5%B1%82%E7%BA%A7-64.OewK_W3z.png",m=JSON.parse('{"title":"函数执行空间限定符","description":"","frontmatter":{},"headers":[{"level":1,"title":"函数执行空间限定符","slug":"函数执行空间限定符"},{"level":2,"title":"\\\\_\\\\_simt\\\\_vf\\\\_\\\\_","slug":"__simt_vf__"},{"level":2,"title":"\\\\_\\\\_simt\\\\_callee\\\\_\\\\_","slug":"__simt_callee__"}],"relativePath":"api/SIMT-API/SIMD与SIMT混合编程简介/扩展语法/函数执行空间限定符-142.md","filePath":"api/SIMT-API/SIMD与SIMT混合编程简介/扩展语法/函数执行空间限定符-142.md"}'),i={name:"api/SIMT-API/SIMD与SIMT混合编程简介/扩展语法/函数执行空间限定符-142.md"};function n(d,t,r,o,p,c){return s(),e("div",null,[...t[0]||(t[0]=[_('<h1 id="函数执行空间限定符" tabindex="-1">函数执行空间限定符 <a class="header-anchor" href="#函数执行空间限定符" aria-label="Permalink to &quot;函数执行空间限定符&quot;">​</a></h1><p>SIMD与SIMT混合编程涉及多种类型的函数，它们之间遵循严格的调用关系和层级约束。本章节将会介绍整体函数类型和调用关系，再详细展开每种函数的定义、调用语法及约束。</p><p>SIMD与SIMT混合编程中涉及的函数类型如下表所示：</p><table tabindex="0"><thead><tr><th>函数执行空间限定符</th><th>函数功能</th><th>调用方式</th></tr></thead><tbody><tr><td><strong>global</strong> <strong>aicore</strong></td><td>算子入口，协调VF执行</td><td>Host侧通过&lt;&lt;&lt;...&gt;&gt;&gt;调用</td></tr><tr><td><strong>aicore</strong></td><td>Device侧辅助函数</td><td>核函数或同级函数调用</td></tr><tr><td><strong>simt_vf</strong></td><td>线程级并行计算任务</td><td>通过SIMT提供的asc_vf_call接口调用</td></tr><tr><td><strong>simd_vf</strong></td><td>向量级并行计算任务</td><td>通过SIMD提供的asc_vf_call接口调用</td></tr><tr><td><strong>simt_callee</strong></td><td>SIMT VF的子函数</td><td>SIMT VF内部调用</td></tr><tr><td><strong>simd_callee</strong></td><td>SIMD VF的子函数</td><td>SIMD VF内部调用</td></tr><tr><td>constexpr <strong>aicore</strong></td><td>编译期执行的Device侧辅助函数</td><td>Device侧函数内部均可调用</td></tr></tbody></table><p>函数调用关系如下图所示：</p><p><img src="'+l+`" alt=""></p><h2 id="simt-vf" tabindex="-1">__simt_vf__ <a class="header-anchor" href="#simt-vf" aria-label="Permalink to &quot;\\_\\_simt\\_vf\\_\\_&quot;">​</a></h2><p>__simt_vf__用于标记SIMT VF入口函数，函数无返回值。使用asc_vf_call接口调用SIMT VF入口函数，启动VF子任务。函数内可使用SIMT内置变量：threadIdx、blockIdx、blockDim、gridDim。函数定义示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simt_vf__ inline void function_name(</span></span>
<span class="line"><span>    __gm__ uint32_t* gm_param, </span></span>
<span class="line"><span>    __ubuf__ float* ubuf_param, </span></span>
<span class="line"><span>    uint64_t scalar_param, ...);</span></span></code></pre></div><p>SIMT VF函数定义中的关键修饰符说明如下：</p><table tabindex="0"><thead><tr><th>修饰符</th><th>作用</th></tr></thead><tbody><tr><td><strong>simt_vf</strong></td><td>函数标识符，标识SIMT VF函数。</td></tr><tr><td>inline</td><td>建议内联，实际是否内联由编译器决定。</td></tr><tr><td><strong>gm</strong></td><td>内存空间修饰符，标识内存空间为GM。</td></tr><tr><td><strong>ubuf</strong></td><td>内存空间修饰符，标识内存空间为UB。</td></tr></tbody></table><p>通过SIMT的<a href="./核函数配置-147.html#section18153457192520">asc_vf_call</a>接口在核函数或__aicore__函数中调用，调用示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asc_vf_call&lt;function_name&gt;(dim3(blockDim), arg1, arg2, ...);</span></span></code></pre></div><p>SIMT VF函数有以下约束：</p><ul><li>入参仅支持Ascend C的<a href="./内置数据类型-144.html">内置数据类型</a>（int32_t、uint32_t、float、half等）及其组成的指针、数组、结构体类型，且指针类型必须指向GM或者UB内存。</li><li>函数返回类型必须是void。</li><li>SIMT VF内只能调用__simt_callee__函数或constexpr __aicore__函数。</li></ul><h2 id="simt-callee" tabindex="-1">__simt_callee__ <a class="header-anchor" href="#simt-callee" aria-label="Permalink to &quot;\\_\\_simt\\_callee\\_\\_&quot;">​</a></h2><p>__simt_callee__子函数是SIMT VF函数内部调用的辅助函数，函数内部可以使用SIMT内置变量。定义示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simt_callee__ uint32_t simt_helper(__gm__ uint32_t* gm_param, __ubuf__ float* ubuf_param, uint64_t scalar_param, ...);</span></span></code></pre></div><p>调用示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t result = simt_helper(arg1, arg2, ...);</span></span></code></pre></div><p>该函数有以下约束：</p><ul><li>入参仅支持Ascend C的<a href="./内置数据类型-144.html">内置数据类型</a>（int32_t、uint32_t、float、half等）及对应的指针类型。</li><li>函数返回值只能是Ascend C的<a href="./内置数据类型-144.html">内置数据类型</a>（int32_t、uint32_t、float、half等）及对应的指针类型。</li><li>函数内只能调用__simt_callee__函数或constexpr __aicore__函数。</li></ul>`,22)])])}const g=a(i,[["render",n]]);export{m as __pageData,g as default};
